import React, { useState } from 'react';
import { Trash2, Plus, Users, Play, Clock, Layers, Calendar, ShieldCheck, MapPin } from 'lucide-react';

// Helper to add hours to a time string (HH:mm)
const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const newH = h + hours;
  return `${String(newH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const distributeSubjects = (subjectList, daysCount) => {
  const sorted = [...subjectList].sort((a, b) => a.code.localeCompare(b.code));
  const result = Array.from({ length: daysCount }, () => []);
  sorted.forEach((subject, index) => {
    result[index % daysCount].push(subject);
  });
  return result;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(1);
  const [examDates, setExamDates] = useState(['']);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(1); // FIXED: No longer locked to 1
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 1);
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const handleAddProctor = () => {
    if (!pName || !pDayStart || !pDayEnd || !pTimeStart || !pTimeEnd) return alert("Fill all proctor fields!");
    onUpdate('proctors', [...proctors, { 
      id: Date.now(), name: pName.toUpperCase(), 
      dayStart: pDayStart, dayEnd: pDayEnd,
      timeStart: pTimeStart, timeEnd: pTimeEnd 
    }]);
    setPName("");
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert("No subjects found for this year level!");
    if (examDates.some(d => !d)) return alert("Please set all exam dates!");

    const dailySplit = distributeSubjects(yearSubjects, examDays);
    const finalGeneratedData = [];

    // Tracks used resources for THIS specific generation run to prevent internal overlaps
    let localUsedRooms = [];
    let localUsedProctors = [];

    for (let dayIdx = 0; dayIdx < dailySplit.length; dayIdx++) {
      const daySubjects = dailySplit[dayIdx];
      const currentDate = examDates[dayIdx];

      // LOGIC: 1 Subject = 1 Hour. Calculate block end time automatically.
      const duration = daySubjects.length; 
      const calculatedEndTime = addHours(startTime, duration);

      // 1. GET ALL POTENTIAL ROOMS (Local + Global Fallback)
      let roomPool = [...rooms];
      if (roomSource === "Global") {
        roomPool = allDepartments.flatMap(d => d.rooms);
      }

      // Filter for availability (Not in global schedule AND not used yet in this loop)
      let availableRooms = roomPool.filter(r => 
        !globalSchedule.some(as => as.room === r.number && as.exam_date === currentDate && (startTime < as.end_time && calculatedEndTime > as.start_time)) &&
        !localUsedRooms.includes(r.number)
      ).sort((a, b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      // 2. GET ALL POTENTIAL PROCTORS
      let proctorPool = [...proctors];
      if (proctorSource === "Global") {
        proctorPool = allDepartments.flatMap(d => d.proctors);
      }

      // 3. ASSIGN PER SECTION
      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;

        // Find a room for this specific section
        const selectedRoom = availableRooms[s]; // Takes the next available unique room
        if (!selectedRoom) return alert(`Not enough rooms for Section ${sectionID} on Day ${dayIdx+1}`);
        localUsedRooms.push(selectedRoom.number);

        // Find a proctor for this specific section (Must fit in time window)
        const validProctor = proctorPool.find(p => 
            currentDate >= p.dayStart && currentDate <= p.dayEnd &&
            startTime >= p.timeStart && calculatedEndTime <= p.timeEnd && // SHIFT WINDOW CHECK
            !globalSchedule.some(as => as.proctor === p.name && as.exam_date === currentDate && (startTime < as.end_time && calculatedEndTime > as.start_time)) &&
            !localUsedProctors.includes(p.name)
        );

        if (!validProctor) return alert(`No available proctor for Section ${sectionID} during ${startTime}-${calculatedEndTime}`);
        localUsedProctors.push(validProctor.name);

        daySubjects.forEach(sub => {
          finalGeneratedData.push({
            subject_code: sub.code,
            subject_name: sub.name,
            section: sectionID,
            year_level: selectedYear,
            dept_code: deptCode,
            exam_date: currentDate,
            start_time: startTime,
            end_time: calculatedEndTime, // AUTO CALCULATED
            room: selectedRoom.number,
            proctor: validProctor.name
          });
        });
      }
      // Reset local tracking for the next exam day
      localUsedRooms = [];
      localUsedProctors = [];
    }
    onGenerate(finalGeneratedData, examDates);
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden mb-12">
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <h2 className="text-3xl font-black uppercase tracking-tighter italic">{deptName}</h2>
      </div>

      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-10">
        {activeTab === 'proctors' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-5 gap-4 bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100">
              <input value={pName} onChange={e=>setPName(e.target.value)} placeholder="NAME" className="p-3 rounded-xl text-xs font-bold" />
              <div className="flex gap-1"><input type="date" value={pDayStart} onChange={e=>setPDayStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /><input type="date" value={pDayEnd} onChange={e=>setPDayEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
              <div className="flex gap-1"><input type="time" value={pTimeStart} onChange={e=>setPTimeStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /><input type="time" value={pTimeEnd} onChange={e=>setPTimeEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px]" /></div>
              <button onClick={handleAddProctor} className="bg-emerald-600 text-white rounded-xl font-black text-[10px] uppercase">Add Proctor</button>
            </div>
            {proctors.map(p => (
                <div key={p.id} className="flex justify-between p-4 bg-white border rounded-2xl">
                    <span className="font-black text-xs uppercase">{p.name} | <span className="text-blue-500">{p.timeStart}-{p.timeEnd}</span></span>
                    <button onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))}><Trash2 size={16} className="text-slate-300"/></button>
                </div>
            ))}
          </div>
        )}

        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-widest">Temporal Logic</h4>
                <div>
                    <label className="text-[10px] text-slate-500 uppercase block mb-2">Exam Days</label>
                    <input type="number" value={examDays} onChange={e=>handleExamDayChange(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl text-xl font-black text-blue-400" />
                </div>
                <div className="space-y-2">{examDates.map((d, i) => (<input key={i} type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-slate-800 p-3 rounded-xl text-xs font-bold" />))}</div>
                <div>
                    <label className="text-[10px] text-slate-500 uppercase block mb-2">Start Time</label>
                    <input type="time" value={startTime} onChange={e=>setStartTime(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-blue-400" />
                    <p className="text-[9px] text-slate-500 mt-2 italic">* End time is calculated automatically (1hr/subject)</p>
                </div>
              </div>

              <div className="space-y-6">
                <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-widest">Section Parameters</h4>
                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-[10px] text-slate-500 uppercase block mb-2">Year Level</label>
                        <select value={selectedYear} onChange={e=>setSelectedYear(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-xs text-blue-400">
                            {[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="text-[10px] text-slate-500 uppercase block mb-2">Total Sections</label>
                        <input type="number" value={sectionCount} onChange={e=>setSectionCount(Number(e.target.value))} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-emerald-400" />
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <select value={proctorSource} onChange={e=>setProctorSource(e.target.value)} className="bg-slate-800 p-3 rounded-xl text-[10px] font-black uppercase"><option>Department</option><option>Global</option></select>
                    <select value={roomSource} onChange={e=>setRoomSource(e.target.value)} className="bg-slate-800 p-3 rounded-xl text-[10px] font-black uppercase"><option>Department</option><option>Global</option></select>
                </div>
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-8 rounded-[2rem] font-black uppercase tracking-[0.3em] flex items-center justify-center gap-4 hover:bg-blue-500 transition-all shadow-2xl shadow-blue-900/40">
                  <Play size={24} fill="currentColor" /> Generate Schedule
                </button>
              </div>
            </div>
          </div>
        )}

        {/* --- SUBJECTS TAB --- */}
        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-2 bg-slate-50 p-4 rounded-2xl">
              <select className="p-2 rounded-lg text-xs font-bold" onChange={(e) => setSelectedYear(e.target.value)}>{[1,2,3,4,5].map(y => <option key={y} value={y}>Year {y}</option>)}</select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-2 rounded-lg text-xs font-bold" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value; const n = document.getElementById(`sN-${deptId}`).value;
                if(c && n) {
                    onUpdate('subjects', { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: c.toUpperCase(), name: n }] });
                    document.getElementById(`sC-${deptId}`).value = ''; document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-lg"><Plus /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">{subjects[selectedYear].map((s, i) => (<div key={i} className="flex justify-between p-3 bg-white border rounded-xl items-center font-black text-xs">{s.code}: {s.name} <button onClick={() => onUpdate('subjects', {...subjects, [selectedYear]: subjects[selectedYear].filter((_,idx)=>idx!==i)}) }><Trash2 size={14} className="text-slate-300" /></button></div>))}</div>
          </div>
        )}

        {/* --- ROOMS TAB --- */}
        {activeTab === 'rooms' && (
          <div className="space-y-4">
            <div className="flex gap-2">
                <input value={roomNum} onChange={e=>setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-3 border rounded-xl text-xs font-bold" />
                <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Department'}]); setRoomNum(""); } }} className="bg-amber-600 text-white px-4 rounded-xl text-[10px] font-black uppercase">Dept</button>
                <button onClick={() => { if(roomNum){ onUpdate('rooms', [...rooms, {id: Date.now(), number: roomNum.toUpperCase(), type: 'Global'}]); setRoomNum(""); } }} className="bg-slate-800 text-white px-4 rounded-xl text-[10px] font-black uppercase">Global</button>
            </div>
            <div className="grid grid-cols-4 gap-2">{rooms.map(r => (<div key={r.id} className="p-4 bg-slate-50 rounded-xl text-center relative group"><span className="font-black text-lg">{r.number}</span><span className="block text-[8px] uppercase font-black text-slate-400">{r.type}</span><button className="absolute top-1 right-1 opacity-0 group-hover:opacity-100" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={12}/></button></div>))}</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
